using Microsoft.EntityFrameworkCore;using Microsoft.EntityFrameworkCore.Storage;
using System.Text.RegularExpressions;
namespace Decont;
public static class SchemaUpgrades {
 public static async Task Apply(Db db){
  var ddl=db.Database.GenerateCreateScript();await using var tx=await db.Database.BeginTransactionAsync();
  foreach(System.Text.RegularExpressions.Match table in Regex.Matches(ddl,@"CREATE TABLE ""(?:ReportAttachments|Preferences|Comments|Assignments|SchemaReleases|SupplierAccounts|DocumentReviews|DocumentGroups|ExtractionAttempts|DocumentEvents|FinancePolicies|FxProposals|FxDecisions|Calculations|TaxPolicies|TaxPolicyDecisions|VerifiedVatComponents|ReportResets|ReportRestores|BankTreatments|BankTreatmentRevocations|FinanceAcceptanceRecords)"" \(.*?\n\);",RegexOptions.Singleline))await db.Database.ExecuteSqlRawAsync(table.Value.Replace("CREATE TABLE ","CREATE TABLE IF NOT EXISTS "));
  foreach(var column in new[]{("Lines","FinancialRounding","INTEGER NULL"),("Lines","FinanceRon",db.Database.IsNpgsql()?"numeric(20,6) NULL":"TEXT NULL"),("Lines","FxDecisionId",db.Database.IsNpgsql()?"uuid NULL":"TEXT NULL"),("Lines","CalculationId",db.Database.IsNpgsql()?"uuid NULL":"TEXT NULL"),("Lines","CalculatedJson","TEXT NULL"),("Lines","CalculationHash","TEXT NULL"),("Lines","RoundingRon",db.Database.IsNpgsql()?"numeric(20,6) NOT NULL DEFAULT 0":"TEXT NOT NULL DEFAULT '0'"),("Jobs","StartedAt",db.Database.IsNpgsql()?"timestamp with time zone NULL":"TEXT NULL"),("Jobs","CompletedAt",db.Database.IsNpgsql()?"timestamp with time zone NULL":"TEXT NULL"),("Jobs","FailureCode","TEXT NULL"),("ReportAttachments","UploadedBy","TEXT NOT NULL DEFAULT ''"),("ReportAttachments","Capture","BOOLEAN NOT NULL DEFAULT FALSE"),("Reports","EmployeeName","TEXT NOT NULL DEFAULT ''"),("Reports","EmployeeWorker","TEXT NOT NULL DEFAULT ''"),("Reports","DepartmentCode","TEXT NOT NULL DEFAULT ''"),("Reports","Payment","TEXT NULL"),("Reports","CardId",db.Database.IsNpgsql()?"uuid NULL":"TEXT NULL"),("Lines","VatOverrideReason","TEXT NULL"),("Decisions","RevisionHash","TEXT NOT NULL DEFAULT ''"),("Batches","FileName","TEXT NOT NULL DEFAULT ''"),("Notices","Hidden","BOOLEAN NOT NULL DEFAULT FALSE")}){
   await using var command=db.Database.GetDbConnection().CreateCommand();command.Transaction=tx.GetDbTransaction();command.CommandText=db.Database.IsNpgsql()?"SELECT column_name FROM information_schema.columns WHERE table_schema='public' AND table_name='"+column.Item1+"'":"PRAGMA table_info(\""+column.Item1+"\")";var names=new List<string>();await using(var reader=await command.ExecuteReaderAsync()){while(await reader.ReadAsync())names.Add(reader.GetString(db.Database.IsNpgsql()?0:1));}if(!names.Contains(column.Item2))await db.Database.ExecuteSqlRawAsync("ALTER TABLE \""+column.Item1+"\" ADD COLUMN \""+column.Item2+"\" "+column.Item3);
  }
  foreach(System.Text.RegularExpressions.Match index in Regex.Matches(ddl,@"CREATE (?:UNIQUE )?INDEX ""[^""]+"" ON ""(?:ReportAttachments|Preferences|Comments|Assignments|SchemaReleases|SupplierAccounts|DocumentReviews|DocumentGroups|ExtractionAttempts|DocumentEvents|FinancePolicies|FxProposals|FxDecisions|Calculations|TaxPolicies|TaxPolicyDecisions|VerifiedVatComponents|ReportResets|ReportRestores|BankTreatments|BankTreatmentRevocations|FinanceAcceptanceRecords)"".*?;"))await db.Database.ExecuteSqlRawAsync(index.Value.Replace("CREATE INDEX ","CREATE INDEX IF NOT EXISTS ").Replace("CREATE UNIQUE INDEX ","CREATE UNIQUE INDEX IF NOT EXISTS "));
  foreach(var table in new[]{"Audits","Snapshots","Decisions","Reviews","Comments","ExtractionAttempts","DocumentEvents","FinancePolicies","FxProposals","FxDecisions","Calculations","TaxPolicies","TaxPolicyDecisions","VerifiedVatComponents","ReportResets","ReportRestores","BankTreatments","BankTreatmentRevocations","FinanceAcceptanceRecords","Transactions"}){if(db.Database.IsNpgsql()){await db.Database.ExecuteSqlRawAsync("CREATE OR REPLACE FUNCTION decont_immutable_evidence() RETURNS trigger LANGUAGE plpgsql AS $$ BEGIN RAISE EXCEPTION 'Immutable evidence'; END $$;");await db.Database.ExecuteSqlRawAsync("DROP TRIGGER IF EXISTS immutable_evidence ON \""+table+"\"; CREATE TRIGGER immutable_evidence BEFORE UPDATE OR DELETE ON \""+table+"\" FOR EACH ROW EXECUTE FUNCTION decont_immutable_evidence();");}else{await db.Database.ExecuteSqlRawAsync("CREATE TRIGGER IF NOT EXISTS immutable_update_"+table+" BEFORE UPDATE ON \""+table+"\" BEGIN SELECT RAISE(ABORT, 'Immutable evidence'); END;");await db.Database.ExecuteSqlRawAsync("CREATE TRIGGER IF NOT EXISTS immutable_delete_"+table+" BEFORE DELETE ON \""+table+"\" BEGIN SELECT RAISE(ABORT, 'Immutable evidence'); END;");}}
  if(!await db.SchemaReleases.AnyAsync(x=>x.Id==3)){db.SchemaReleases.Add(new(){Id=3,Name="Receipt extraction and platform workflows"});await db.SaveChangesAsync();}if(!await db.SchemaReleases.AnyAsync(x=>x.Id==4)){db.SchemaReleases.Add(new(){Id=4,Name="Report header and employee context"});await db.SaveChangesAsync();}if(!await db.SchemaReleases.AnyAsync(x=>x.Id==5)){db.SchemaReleases.Add(new(){Id=5,Name="Versioned OCR document review and source groups"});await db.SaveChangesAsync();}if(!await db.SchemaReleases.AnyAsync(x=>x.Id==6)){db.SchemaReleases.Add(new(){Id=6,Name="Document outbox and processing diagnostics"});await db.SaveChangesAsync();}if(!await db.SchemaReleases.AnyAsync(x=>x.Id==7)){db.SchemaReleases.Add(new(){Id=7,Name="Finance FX policies and immutable calculation ledger"});await db.SaveChangesAsync();}if(!await db.SchemaReleases.AnyAsync(x=>x.Id==8)){db.SchemaReleases.Add(new(){Id=8,Name="Controlled tax policies and financial provenance"});await db.SaveChangesAsync();}await tx.CommitAsync();
 }
}

